import{_ as a,o as i,c as s,a3 as t}from"./chunks/framework.B5WAEDB7.js";const k=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1786258560000}'),n={name:"guide/faq.md"};function r(o,e,l,d,h,c){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>框架层面的高频故障速查。这些坑的共同点是<strong>没有异常、没有日志、静默失效</strong>——知道去哪儿看就能秒解，不知道就能耗一天。每条都对照框架源码核实。</p><nav class="table-of-contents"><ul><li><a href="#模块与装配">模块与装配</a><ul><li><a href="#我的模块写好了-但服务一个都没注册">我的模块写好了，但服务一个都没注册</a></li><li><a href="#dependson-要把间接依赖也列上吗">[DependsOn] 要把间接依赖也列上吗</a></li><li><a href="#启动时抛出动态-api-装配异常">启动时抛出动态 API 装配异常</a></li><li><a href="#代码该写在哪个生命周期钩子里">代码该写在哪个生命周期钩子里</a></li></ul></li><li><a href="#依赖注入">依赖注入</a><ul><li><a href="#运行期抛「无法解析服务」">运行期抛「无法解析服务」</a></li><li><a href="#我实现了同一个接口-但用的还是框架的默认实现">我实现了同一个接口，但用的还是框架的默认实现</a></li><li><a href="#一个实现类实现了多个接口-只有一个能注入">一个实现类实现了多个接口，只有一个能注入</a></li><li><a href="#想让某个类完全不被自动注册">想让某个类完全不被自动注册</a></li></ul></li><li><a href="#aop-与拦截器">AOP 与拦截器</a><ul><li><a href="#unitofwork-cacheable-标了没生效">[UnitOfWork] / [Cacheable] 标了没生效</a></li><li><a href="#匿名端点调用应用服务时永久挂起">匿名端点调用应用服务时永久挂起</a></li><li><a href="#怎么加自己的拦截器">怎么加自己的拦截器</a></li></ul></li><li><a href="#工作单元与事务">工作单元与事务</a><ul><li><a href="#我的应用服务方法没有事务">我的应用服务方法没有事务</a></li><li><a href="#内层调了-rollbackasync-外层还能提交吗">内层调了 RollbackAsync，外层还能提交吗</a></li><li><a href="#requiresnew-到底给不给我一个独立事务">requiresNew 到底给不给我一个独立事务</a></li><li><a href="#本地事件和分布式事件的发布时机有什么区别">本地事件和分布式事件的发布时机有什么区别</a></li></ul></li><li><a href="#动态-api">动态 API</a><ul><li><a href="#生成的路由和我预期的不一样">生成的路由和我预期的不一样</a></li><li><a href="#分页方法收不到请求体">分页方法收不到请求体</a></li><li><a href="#改了动词映射表-前端全-404-了">改了动词映射表，前端全 404 了</a></li></ul></li><li><a href="#数据访问">数据访问</a><ul><li><a href="#给实体加了字段-部署后报「列不存在」">给实体加了字段，部署后报「列不存在」</a></li><li><a href="#实体变更日志-diff-一条都没有">实体变更日志（Diff）一条都没有</a></li><li><a href="#写操作报-parameter-constant1001-already-been-defined">写操作报 Parameter &#39;@constant1001&#39; already been defined</a></li><li><a href="#租户上下文里改不了全局数据">租户上下文里改不了全局数据</a></li></ul></li><li><a href="#缓存与事件">缓存与事件</a><ul><li><a href="#本地事件处理器不触发">本地事件处理器不触发</a></li><li><a href="#怎么在缓存上执行-lua-脚本">怎么在缓存上执行 Lua 脚本</a></li></ul></li><li><a href="#还没解决">还没解决？</a></li></ul></nav><hr><h2 id="模块与装配" tabindex="-1">模块与装配 <a class="header-anchor" href="#模块与装配" aria-label="Permalink to &quot;模块与装配&quot;">​</a></h2><h3 id="我的模块写好了-但服务一个都没注册" tabindex="-1">我的模块写好了，但服务一个都没注册 <a class="header-anchor" href="#我的模块写好了-但服务一个都没注册" aria-label="Permalink to &quot;我的模块写好了，但服务一个都没注册&quot;">​</a></h3><p><code>ConfigureServices</code> 只会被框架在<strong>依赖图内</strong>调用。检查两点：</p><ol><li>你的模块有没有出现在启动模块（或其某个上游模块）的 <code>[DependsOn]</code> 里。不在依赖图里的模块类，框架根本不认识它。</li><li>有没有在宿主里额外手写 <code>services.AddMyModule(...)</code>。模块自己的 <code>ConfigureServices</code> 已经会跑一次，宿主再调一次就是<strong>重复注册</strong>。宿主只用 <code>[DependsOn]</code> 挂模块，不重复接线。</li></ol><h3 id="dependson-要把间接依赖也列上吗" tabindex="-1"><code>[DependsOn]</code> 要把间接依赖也列上吗 <a class="header-anchor" href="#dependson-要把间接依赖也列上吗" aria-label="Permalink to &quot;`[DependsOn]` 要把间接依赖也列上吗&quot;">​</a></h3><p>不用。<strong>只写直接依赖</strong>——间接依赖由被依赖模块自己声明，框架按依赖图拓扑排序装配，重复列举没有收益，只会让依赖关系失真。</p><h3 id="启动时抛出动态-api-装配异常" tabindex="-1">启动时抛出动态 API 装配异常 <a class="header-anchor" href="#启动时抛出动态-api-装配异常" aria-label="Permalink to &quot;启动时抛出动态 API 装配异常&quot;">​</a></h3><p>这是<strong>故意的</strong>。<code>DynamicApiOptions.ThrowOnGenerationFailure</code> 默认 <code>true</code>：任一应用服务生成控制器失败就中断装配并抛聚合异常，异常信息里有具体是哪个服务、哪个方法。</p><p>设成 <code>false</code> 会改为只记日志并跳过——该服务的全部端点就从路由表里静默消失，前端拿到 404 却查不出所以然。<strong>不建议</strong>关掉。</p><h3 id="代码该写在哪个生命周期钩子里" tabindex="-1">代码该写在哪个生命周期钩子里 <a class="header-anchor" href="#代码该写在哪个生命周期钩子里" aria-label="Permalink to &quot;代码该写在哪个生命周期钩子里&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你要做的事</th><th>钩子</th></tr></thead><tbody><tr><td>注册服务、绑定选项</td><td><code>ConfigureServices</code></td></tr><tr><td>挂拦截器注册器、预设其他模块要读的选项</td><td><code>PreConfigureServices</code></td></tr><tr><td>所有模块注册完后做最终覆盖</td><td><code>PostConfigureServices</code></td></tr><tr><td>接中间件、映射端点</td><td><code>OnApplicationInitialization</code></td></tr><tr><td>要插在管道最前面（如 Webhook 校验）</td><td><code>OnPreApplicationInitialization</code></td></tr><tr><td>一切就绪后再做（如把库里的任务同步进调度器）</td><td><code>OnPostApplicationInitialization</code></td></tr><tr><td>释放资源</td><td><code>OnApplicationShutdown</code>（<strong>逆序</strong>执行，与其余六个钩子相反）</td></tr></tbody></table><p>拿 <code>IApplicationBuilder</code> 的 <code>context.GetApplicationBuilder()</code> 等扩展方法来自 <code>XiHan.Framework.Web.Core</code>，纯类库模块里没有。</p><hr><h2 id="依赖注入" tabindex="-1">依赖注入 <a class="header-anchor" href="#依赖注入" aria-label="Permalink to &quot;依赖注入&quot;">​</a></h2><h3 id="运行期抛「无法解析服务」" tabindex="-1">运行期抛「无法解析服务」 <a class="header-anchor" href="#运行期抛「无法解析服务」" aria-label="Permalink to &quot;运行期抛「无法解析服务」&quot;">​</a></h3><p>最常见的是<strong>领域服务</strong>。领域服务接口通常不带 <code>ITransientDependency</code> / <code>IScopedDependency</code> / <code>ISingletonDependency</code> 标记接口，约定注册扫不到，必须手写：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddScoped</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IInvoiceDomainService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">InvoiceDomainService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();</span></span></code></pre></div><p>对比：应用服务（<code>ApplicationServiceBase</code> 已实现 <code>ITransientDependency</code>）与仓储（基类带 <code>IScopedDependency</code>）都会被自动注册，不用手写。</p><h3 id="我实现了同一个接口-但用的还是框架的默认实现" tabindex="-1">我实现了同一个接口，但用的还是框架的默认实现 <a class="header-anchor" href="#我实现了同一个接口-但用的还是框架的默认实现" aria-label="Permalink to &quot;我实现了同一个接口，但用的还是框架的默认实现&quot;">​</a></h3><p>框架用 <strong><code>TryAdd</code></strong> 注册默认实现，且<strong>先于</strong>你的模块执行。你再 <code>TryAdd</code>（包括很多 <code>AddXxx</code> 扩展方法内部就是 <code>TryAdd</code>）会被<strong>静默忽略</strong>。</p><p>覆盖必须用 <code>Replace</code>：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Replace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ServiceDescriptor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Singleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IAiProviderConfigStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DbAiProviderConfigStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;());</span></span></code></pre></div><p>或走特性：<code>[Dependency(ServiceLifetime.Scoped, ReplaceServices = true)]</code>。</p><p>替换时<strong>生命周期要与被替换者一致</strong>，否则解析时抛作用域校验异常（Singleton 依赖 Scoped 是非法的）。</p><h3 id="一个实现类实现了多个接口-只有一个能注入" tabindex="-1">一个实现类实现了多个接口，只有一个能注入 <a class="header-anchor" href="#一个实现类实现了多个接口-只有一个能注入" aria-label="Permalink to &quot;一个实现类实现了多个接口，只有一个能注入&quot;">​</a></h3><p>约定注册默认只把实现类暴露为「类名去掉前导 <code>I</code> 后同名」的那个接口（<code>OrderService</code> → <code>IOrderService</code>）。要额外暴露：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ExposeServices</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INotifiable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IncludeDefaults</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OrderService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IOrderService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INotifiable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IScopedDependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { }</span></span></code></pre></div><p>同接口多实现按 key 区分用 <code>[ExposeKeyedService&lt;IPaymentGateway&gt;(&quot;alipay&quot;)]</code>，消费侧 <code>[FromKeyedServices(&quot;alipay&quot;)]</code>。</p><h3 id="想让某个类完全不被自动注册" tabindex="-1">想让某个类完全不被自动注册 <a class="header-anchor" href="#想让某个类完全不被自动注册" aria-label="Permalink to &quot;想让某个类完全不被自动注册&quot;">​</a></h3><p>类上加 <code>[DisableConventionalRegistration]</code>，然后自己手写注册。</p><hr><h2 id="aop-与拦截器" tabindex="-1">AOP 与拦截器 <a class="header-anchor" href="#aop-与拦截器" aria-label="Permalink to &quot;AOP 与拦截器&quot;">​</a></h2><h3 id="unitofwork-cacheable-标了没生效" tabindex="-1"><code>[UnitOfWork]</code> / <code>[Cacheable]</code> 标了没生效 <a class="header-anchor" href="#unitofwork-cacheable-标了没生效" aria-label="Permalink to &quot;`[UnitOfWork]` / `[Cacheable]` 标了没生效&quot;">​</a></h3><p><strong>最可能的原因：服务的注册类型不是接口。</strong></p><p>框架的 AOP 走 Castle 的 <code>CreateInterfaceProxyWithTarget</code>，<code>AddCastleDynamicProxy</code> 只处理 <code>ServiceType.IsInterface</code> 为真的服务描述器。所以：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddScoped</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MyService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ❌ 注册为自身类型 → 不会被代理，特性静默失效</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddScoped</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IMyService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MyService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅ 接口 → 会被代理</span></span></code></pre></div><p>其次检查：类型有没有被列进 <code>DynamicProxyIgnoreTypes</code>。</p><h3 id="匿名端点调用应用服务时永久挂起" tabindex="-1">匿名端点调用应用服务时永久挂起 <a class="header-anchor" href="#匿名端点调用应用服务时永久挂起" aria-label="Permalink to &quot;匿名端点调用应用服务时永久挂起&quot;">​</a></h3><p>匿名端点（Minimal API、OAuth 回调等）不经过工作单元中间件，而应用服务被 Castle 代理包着，拦截器会急切开事务从而死锁。</p><p>解法是<strong>绕开代理</strong>：注入真正的依赖直连，或用 <code>ProxyHelper.UnProxy(service)</code> 取真实目标实例再调。</p><h3 id="怎么加自己的拦截器" tabindex="-1">怎么加自己的拦截器 <a class="header-anchor" href="#怎么加自己的拦截器" aria-label="Permalink to &quot;怎么加自己的拦截器&quot;">​</a></h3><p>写一个 <code>IXiHanInterceptor</code> 实现 + 一个决定「拦谁」的注册器，在 <code>PreConfigureServices</code> 里 <code>services.OnRegistered(注册器)</code> 挂上。完整示例见 <a href="./extending#配方-c-自定义-aop-拦截器">扩展与二次开发 · 自定义 AOP 拦截器</a>。</p><hr><h2 id="工作单元与事务" tabindex="-1">工作单元与事务 <a class="header-anchor" href="#工作单元与事务" aria-label="Permalink to &quot;工作单元与事务&quot;">​</a></h2><h3 id="我的应用服务方法没有事务" tabindex="-1">我的应用服务方法没有事务 <a class="header-anchor" href="#我的应用服务方法没有事务" aria-label="Permalink to &quot;我的应用服务方法没有事务&quot;">​</a></h3><p><strong>没标 <code>[UnitOfWork]</code> 就没有环境工作单元。</strong> 框架判定「这个类型要不要被工作单元拦截」的条件是：类或任一方法上有 <code>[UnitOfWork]</code>，<strong>或者</strong>类型实现了 <code>IUnitOfWorkEnabled</code>。而 <code>IUnitOfWorkEnabled</code> 在框架里<strong>没有任何实现者</strong>，<code>ApplicationServiceBase</code> 也没实现它。</p><p>所以写操作要事务，就在方法（或类）上显式标注：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UnitOfWork</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// true = 需要事务</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Task</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">InvoiceDto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CreateInvoiceAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">InvoiceCreateDto</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { … }</span></span></code></pre></div><h3 id="内层调了-rollbackasync-外层还能提交吗" tabindex="-1">内层调了 <code>RollbackAsync</code>，外层还能提交吗 <a class="header-anchor" href="#内层调了-rollbackasync-外层还能提交吗" aria-label="Permalink to &quot;内层调了 `RollbackAsync`，外层还能提交吗&quot;">​</a></h3><p>不能。回滚之后再提交会抛 <code>XiHanException</code>。</p><p>父子工作单元共用同一物理事务，内层判定失败回滚就意味着整体终止——让外层若无其事地提交会产出「接口返回 200 但数据一行没写」。</p><p>同理 <code>SqlSugarClientResolver</code> 的钉住连接判定包含「是否已回滚」：检出已回滚的事务型工作单元会抛出并提示改用 <code>Begin(requiresNew: true)</code>，避免回滚之后的写入落在一条已无事务的连接上被逐条自动提交。</p><h3 id="requiresnew-到底给不给我一个独立事务" tabindex="-1"><code>requiresNew</code> 到底给不给我一个独立事务 <a class="header-anchor" href="#requiresnew-到底给不给我一个独立事务" aria-label="Permalink to &quot;`requiresNew` 到底给不给我一个独立事务&quot;">​</a></h3><p>给。<code>requiresNew</code> 同时意味着<strong>新的逻辑工作单元</strong>和<strong>新的物理连接</strong>——两者缺一，内层就还是跑在外层的连接和事务上。</p><p>用的时候记住语义代价：内层提交后<strong>不再受外层回滚影响</strong>。所以<strong>不要在已经修改过某些行的事务里，再用 <code>requiresNew</code> 去改同一批行</strong>——两条独立连接改同一批行，轻则互相覆盖，重则死锁。</p><h3 id="本地事件和分布式事件的发布时机有什么区别" tabindex="-1">本地事件和分布式事件的发布时机有什么区别 <a class="header-anchor" href="#本地事件和分布式事件的发布时机有什么区别" aria-label="Permalink to &quot;本地事件和分布式事件的发布时机有什么区别&quot;">​</a></h3><p>时机不同，且这个差别是有意为之：</p><ul><li><strong>本地事件</strong>：<strong>提交前</strong>发布。其处理器可能继续写库，这些写入必须落在同一个事务里。</li><li><strong>分布式事件</strong>：循环内只累积，<strong>事务提交成功后</strong>再按 <code>EventOrder</code> 统一发布。这样事务回滚时下游不会收到一份从未落库的数据。</li></ul><p>代价是提交成功后若投递失败事件会丢。发件箱是进程内实现，进程一停即丢——要强投递保证请自行接持久化发件箱。</p><hr><h2 id="动态-api" tabindex="-1">动态 API <a class="header-anchor" href="#动态-api" aria-label="Permalink to &quot;动态 API&quot;">​</a></h2><h3 id="生成的路由和我预期的不一样" tabindex="-1">生成的路由和我预期的不一样 <a class="header-anchor" href="#生成的路由和我预期的不一样" aria-label="Permalink to &quot;生成的路由和我预期的不一样&quot;">​</a></h3><p>三条最容易忘的规则：</p><ol><li><strong>动词前缀会被剥离</strong>：<code>GetUserPageAsync</code> → 动作名 <code>UserPage</code>（不是 <code>GetUserPage</code>），<code>Async</code> 后缀也去掉。</li><li><strong>没有匹配动词前缀时默认 POST</strong>：<code>SwitchTenantAsync</code> → <code>POST /api/Auth/SwitchTenant</code>。</li><li><strong>路由段只由显式 <code>[FromRoute]</code> 参数产生</strong>。普通参数一律落到查询串或请求体，<strong>不会</strong>自动变成 <code>/{id}</code> 路径段。</li></ol><p>前缀匹配要求<strong>词边界</strong>（前缀之后必须是大写字母或下划线），所以 <code>AddressBook</code> 不会被 <code>Add</code> 命中而变成 <code>POST /ressBook</code>，<code>EditorTemplate</code> 也不会被 <code>Edit</code> 命中。</p><p>完整动词表见 <a href="./dynamic-api">动态 API</a>。</p><h3 id="分页方法收不到请求体" tabindex="-1">分页方法收不到请求体 <a class="header-anchor" href="#分页方法收不到请求体" aria-label="Permalink to &quot;分页方法收不到请求体&quot;">​</a></h3><p>方法名以 <code>Get</code> 开头会被推导为 GET，请求体自然绑不上。<strong>分页方法必须显式标 <code>[HttpPost]</code></strong>。方法上显式标注的 <code>[HttpGet]</code> / <code>[HttpPost]</code> 优先于前缀推导。</p><h3 id="改了动词映射表-前端全-404-了" tabindex="-1">改了动词映射表，前端全 404 了 <a class="header-anchor" href="#改了动词映射表-前端全-404-了" aria-label="Permalink to &quot;改了动词映射表，前端全 404 了&quot;">​</a></h3><p>改 <code>Conventions.HttpMethodConventions</code>、<code>PreserveRoutePredicate</code>、<code>UseLowercaseRoutes</code>、<code>Routes.*</code> 中任何一个，都会让<strong>已有接口的 URL 变化</strong>。上线后再动这些开关等于一次破坏性变更，前端必须同步改。</p><hr><h2 id="数据访问" tabindex="-1">数据访问 <a class="header-anchor" href="#数据访问" aria-label="Permalink to &quot;数据访问&quot;">​</a></h2><h3 id="给实体加了字段-部署后报「列不存在」" tabindex="-1">给实体加了字段，部署后报「列不存在」 <a class="header-anchor" href="#给实体加了字段-部署后报「列不存在」" aria-label="Permalink to &quot;给实体加了字段，部署后报「列不存在」&quot;">​</a></h3><p><code>DbInitializer</code> <strong>表存在就跳过建表</strong>（日志里是「表已存在，跳过创建」），它<strong>从不为已有表补列</strong>。</p><p>要么重建数据库，要么手动 <code>ALTER TABLE</code> 补列。框架的定位是「首次启动自动建表 + 播种」，不是迁移工具。</p><h3 id="实体变更日志-diff-一条都没有" tabindex="-1">实体变更日志（Diff）一条都没有 <a class="header-anchor" href="#实体变更日志-diff-一条都没有" aria-label="Permalink to &quot;实体变更日志（Diff）一条都没有&quot;">​</a></h3><p>两个条件必须同时成立：</p><ol><li>配置 <strong><code>XiHan:Data:SqlSugarCore:EnableDiffLog</code> 设为 <code>true</code></strong>——<strong>默认是 <code>false</code></strong>，不开则 Diff AOP 根本不挂载，收集到的差异被直接丢弃；</li><li>写操作走仓储并调用了 <code>.EnableDiffLogEvent(businessData)</code>。</li></ol><p>生产的 <code>appsettings</code> 常被 gitignore，最容易漏的就是第一条。</p><h3 id="写操作报-parameter-constant1001-already-been-defined" tabindex="-1">写操作报 <code>Parameter &#39;@constant1001&#39; already been defined</code> <a class="header-anchor" href="#写操作报-parameter-constant1001-already-been-defined" aria-label="Permalink to &quot;写操作报 `Parameter &#39;@constant1001&#39; already been defined`&quot;">​</a></h3><p>仓储里<strong>显式调用了 <code>.EnableQueryFilter()</code></strong>。</p><p>框架默认 <code>EnableAutoUpdateQueryFilter</code> / <code>EnableAutoDeleteQueryFilter</code> 均为 <code>true</code>，SqlSugar 的 <code>Updateable&lt;T&gt;()</code> / <code>Deleteable&lt;T&gt;()</code> 工厂内部<strong>已经自动挂了一次</strong>过滤。你再显式挂一次，同一份过滤会被烘进 WHERE 两遍、生成同名参数；一旦叠加 Diff 的 <code>GetDiffTable</code> 重查旧值就崩（MySQL 驱动直接抛，PG 驱动容忍重名故不崩，但仍是冗余死条件）。</p><p><strong>解法：把仓储里所有显式 <code>.EnableQueryFilter()</code> 删掉。</strong> <code>.EnableDiffLogEvent()</code> 保留，它单独用是安全的。</p><h3 id="租户上下文里改不了全局数据" tabindex="-1">租户上下文里改不了全局数据 <a class="header-anchor" href="#租户上下文里改不了全局数据" aria-label="Permalink to &quot;租户上下文里改不了全局数据&quot;">​</a></h3><p>这是<strong>有意的写路径边界</strong>：全局租户过滤器为「读共享」放行 <code>TenantId=0</code> 的平台全局行，但<strong>写路径不复用这个口径</strong>——租户上下文内禁止改写/删除非本租户行（含全局行），预读守卫会校验取回行的 <code>TenantId</code>，条件写会自动追加当前租户 Where。</p><p>维护全局 / 跨租户数据的唯一合法入口是<strong>平台态</strong>（无租户上下文，<code>ICurrentTenant.Change(null)</code>）。</p><hr><h2 id="缓存与事件" tabindex="-1">缓存与事件 <a class="header-anchor" href="#缓存与事件" aria-label="Permalink to &quot;缓存与事件&quot;">​</a></h2><h3 id="本地事件处理器不触发" tabindex="-1">本地事件处理器不触发 <a class="header-anchor" href="#本地事件处理器不触发" aria-label="Permalink to &quot;本地事件处理器不触发&quot;">​</a></h3><p>事件总线只自动发现「<strong>以接口为服务类型</strong>」的注册。裸 <code>services.AddTransient&lt;MyHandler&gt;()</code>（注册为具体类）<strong>不会被订阅，静默失败</strong>。</p><p>处理器必须显式加入 <code>XiHanLocalEventBusOptions.Handlers</code>：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddTransient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MyHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">XiHanLocalEventBusOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> o.Handlers.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddIfNotContains</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MyHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)));</span></span></code></pre></div><p>BasicApp 把这两步封装成了 <code>AddSaasLocalEventHandler&lt;T&gt;()</code>。</p><h3 id="怎么在缓存上执行-lua-脚本" tabindex="-1">怎么在缓存上执行 Lua 脚本 <a class="header-anchor" href="#怎么在缓存上执行-lua-脚本" aria-label="Permalink to &quot;怎么在缓存上执行 Lua 脚本&quot;">​</a></h3><p>Lua 执行不在 <code>IDistributedCache</code> 这个通用契约上，而是<strong>可选能力接口</strong> <code>ICacheSupportsLuaScript</code>——通用缓存抽象不应该焊上某个客户端的类型。</p><p>用法是先做类型判断：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">is</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ICacheSupportsLuaScript</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lua</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    CacheScriptResult</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lua.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ScriptEvaluateAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(script, keys, args);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>入参是中立的 <code>object?[]</code>，返回 <code>CacheScriptResult</code>（支持标量、整数、布尔与嵌套数组）。<code>IRedisDelayQueue</code> / <code>IRedisStreamQueue</code> 是名字里就带 Redis 的专用抽象，直接用即可。</p><hr><h2 id="还没解决" tabindex="-1">还没解决？ <a class="header-anchor" href="#还没解决" aria-label="Permalink to &quot;还没解决？&quot;">​</a></h2><ul><li><a href="./extending">扩展与二次开发</a>：模块、替换默认实现、拦截器、动态 API 定制的完整配方</li><li><a href="./modularity">模块系统</a> / <a href="./lifecycle">生命周期</a> / <a href="./dependency-injection">依赖注入</a>：机制本身</li><li><a href="./../packages/">模块总览</a>：逐包的配置项、API 与注意事项</li><li><a href="https://basicapp.docs.xihanfun.com/faq" target="_blank" rel="noreferrer">BasicApp 常见问题</a>：业务系统层面的坑（认证、权限、菜单、前端）</li><li>仍未解决可到 <a href="https://github.com/XiHanFun/XiHan.Framework/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提问</li></ul>',105)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
